      const { dispatchWorkflow } = await import(${JSON.stringify(GH)});
      const ok = dispatchWorkflow(
        "ctx",
        "atomaton-runner.yml",
        ["--repo", "o/r", "--field", "agent=engineer"],
        (message) => process.stderr.write(message + "\\n"),
